#!/usr/bin/env python3
"""Writes the generated region of aead/PROOF.bend: the lemmas proved by
splitting words into their 32 bits (a deep pattern, then {==}).

  python3 gen/proof.py           rewrite the region between
                                 "# BEGIN GENERATED by gen/proof.py: bits"
                                 and "# END GENERATED: bits"
  python3 gen/proof.py --check   only check that it is up to date
"""
import os, sys

HERE = os.path.dirname(os.path.abspath(__file__))
PKG = os.path.join(HERE, "..")


def word(prefix, n=32):
    s = "WNil{}"
    for i in reversed(range(n)):
        s = "WCon{%s%d, %s}" % (prefix, i, s)
    return s


def u32(prefix):
    return "U32{%s}" % word(prefix)


def region():
    out = ["# the low byte of a XOR depends only on the low byte of its first operand\n"
           "def byte_xor_byte(z: U32, k: U32) -> {B.byte(U32.xor(z, k)) == B.byte(U32.xor(B.byte(z), k)) : U32}:\n"
           "  match z k:\n    case %s %s:\n      {==}\n" % (u32("a"), u32("b")),
           "# a word's big-endian bytes are four\n"
           "def be32_len(v: U32) -> {4n == B.len(B.be32(v)) : Nat}:\n"
           "  match v:\n    case %s:\n      {==}\n" % u32("a"),
           "# a byte masked again is itself\n"
           "def byte_byte(h: U32) -> {B.byte(h) == B.byte(B.byte(h)) : U32}:\n"
           "  match h:\n    case %s:\n      {==}\n" % u32("a")]
    return "\n".join(out)


def main():
    path = os.path.join(PKG, "PROOF.bend")
    with open(path, encoding="utf-8", newline="") as f:
        src = f.read()
    begin = "# BEGIN GENERATED by gen/proof.py: bits\n"
    end = "# END GENERATED: bits\n"
    i = src.index(begin) + len(begin)
    j = src.index(end, i)
    new = src[:i] + region() + src[j:]
    if "--check" in sys.argv[1:]:
        if new != src:
            print("PROOF.bend differs from what gen/proof.py generates")
            sys.exit(1)
        print("PROOF.bend is up to date")
        return
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(new)


if __name__ == "__main__":
    main()
